package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: works out their due-total as the screen shows it, binds each of
 * their claims that counts (OPEN or SETTLED) to the figure it has now, unbinds the rest
 * (leaving a held person's OPEN claims, which count in no total, as they are), and moves
 * the person's statement count, last due-total and date (the sheet's today) on.
 *
 * A claim's figure is its settled due, else the figure a statement bound it to, else its live due at
 * the person's grade's rate in force on its date (n/a without one). The due-total adds up the counting
 * claims' figures, skipping n/a; it is n/a when the grade has no rate on today and no counting claim
 * keeps a fixed figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rateRepository,
            SheetClock clock, Out<Statement> statementOut) {
        String sheetId = person.getSheetId();
        LocalDate today = clock.today(sheetId);
        List<Rate> rates = rateRepository.findBySheet(sheetId);
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        int counted = 0;
        for (Claim claim : claims.findByPerson(sheetId, person.getId())) {
            boolean counts = claim.getStatus() == ClaimStatus.OPEN || claim.getStatus() == ClaimStatus.SETTLED;
            if (counts && !person.counts(claim.getStatus())) {
                continue;           // a held person's OPEN claim: in no total, and left as it is
            } else if (!counts) {
                claim.setStated(false);
                claim.setStatedDue(null);
            } else {
                BigDecimal figure = figure(claim, person, rates);
                if (claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null)) fixed = true;
                if (figure != null) sum = sum.add(figure);
                claim.setStated(true);
                claim.setStatedDue(figure);
                counted++;
            }
            claims.save(claim);
        }
        BigDecimal dueTotal = Rate.inForce(rates, person.getGrade(), today).isEmpty() && !fixed ? null : sum;
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statementOut.set(new Statement(dueTotal, counted));
    }

    /** amount × pct / 100, rounded half to even to two decimals, unless already fixed; null when n/a. */
    private static BigDecimal figure(Claim claim, Person person, List<Rate> rates) {
        if (claim.getSettledDue() != null) return claim.getSettledDue();
        if (claim.isStated()) return claim.getStatedDue();
        return Rate.inForce(rates, person.getGrade(), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim made by a person on a sheet. Mutable so an Apply step changes it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private Integer number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, Integer number, BigDecimal settledDue, String openedBy,
            boolean stated, BigDecimal statedDue) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on the sheet: null for a draft (a voided claim keeps its number). */
    public Integer getNumber() { return number; }
    public void setNumber(Integer number) { this.number = number; }
    /** The due fixed when the claim was settled: null while it is live (not settled, or settled without a rate). */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
    /** The user who opened the claim: null until it is opened. */
    public String getOpenedBy() { return openedBy; }
    public void setOpenedBy(String openedBy) { this.openedBy = openedBy; }
    /** Whether the person's last statement bound the claim to {@link #getStatedDue()}. */
    public boolean isStated() { return stated; }
    public void setStated(boolean stated) { this.stated = stated; }
    /** The figure the last statement bound the claim to: null when unbound, or bound without a rate (n/a). */
    public BigDecimal getStatedDue() { return statedDue; }
    public void setStatedDue(BigDecimal statedDue) { this.statedDue = statedDue; }
}
package net.officefloor.hq.app.claim;

/** A claim as the screen shows it: the amount with two decimals, the date as yyyy-MM-dd, the status by name,
 *  the number (null when it has none), the due fixed when it was settled (null while it is live),
 *  who opened it (null until it is opened), whether a statement binds it and the figure it binds it to
 *  (null when unbound or n/a). */
public record ClaimResponse(long id, long personId, String amount, String date, String note, String status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue) {
    public static ClaimResponse from(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate().toString(), claim.getNote(), claim.getStatus().name(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString());
    }
}

